from decimal import Decimal

ZERO = Decimal("0")


def totals_by_customer(orders):
    """Total non-cancelled order amounts per customer.

    Orders with a status of ``"cancelled"`` are skipped; a missing (or
    ``None``) status is treated as active. Amounts are summed as
    ``Decimal`` values and the result is returned as a dict ordered by
    customer ID.
    """
    totals = {}
    for order in orders:
        status = order.get("status")
        if status is not None and str(status).strip().lower() == "cancelled":
            continue

        customer_id = order["customer_id"]
        amount = order.get("amount", ZERO)
        if not isinstance(amount, Decimal):
            amount = Decimal(str(amount))

        totals[customer_id] = totals.get(customer_id, ZERO) + amount

    return {customer_id: totals[customer_id] for customer_id in sorted(totals)}

