# Registry mapping channel name -> handler callable.
_CHANNELS = {
    'email': _email,
    'slack': _slack,
    'sms': _sms,
}


def send(channel, message):
    try:
        handler = _CHANNELS[channel]
    except (KeyError, TypeError):
        # TypeError is raised for unhashable channels (e.g. a list); those are
        # unknown channels too, so they get the same error as before.
        raise ValueError(f'unknown channel: {channel}') from None
    return handler(message)

